class Solution {
public:
    string findSmallestRegion(vector<vector<string>>& regions,
                              string region1, string region2) {
        unordered_map<string, string> parent;
        for (const auto& group : regions) {
            for (int i = 1; i < static_cast<int>(group.size()); ++i) {
                parent[group[i]] = group[0];
            }
        }
        unordered_set<string> ancestors;
        while (!region1.empty()) {
            ancestors.insert(region1);
            region1 = parent.count(region1) ? parent[region1] : "";
        }
        while (!ancestors.count(region2)) {
            region2 = parent[region2];
        }
        return region2;
    }
};
